#include "umicom/studio/compiler_catalogue_v2.h"
#include "umicom/studio/compiler_centre_v2.h"
#include "umicom/studio/compiler_export_v2.h"
#include <stdio.h>
int main(int argc,char **argv)
{ UmiStudioCompilerCentreV2 *centre = NULL; UmiStudioCompilerCentreSnapshotV2 snapshot; UmiStudioCompilerCatalogueV2 catalogue; UmiCompilerCentre *engine; char summary[2048]; size_t index; const char *gcc = argc > 1 ? argv[1] : "gcc"; const char *clang = argc > 2 ? argv[2] : "clang"; const char *umicc = argc > 3 ? argv[3] : ""; if (umi_studio_compiler_centre_v2_create(NULL,&centre) != UMI_STATUS_OK) return 1; if (umi_studio_compiler_centre_v2_register_defaults(centre,gcc,clang,"rustc","zig",umicc,NULL) != UMI_STATUS_OK) { umi_studio_compiler_centre_v2_destroy(centre); return 2; } if (umi_studio_compiler_centre_v2_snapshot(centre,&snapshot) != UMI_STATUS_OK) { umi_studio_compiler_centre_v2_destroy(centre); return 3; } engine = umi_studio_compiler_centre_v2_engine(centre); (void)umi_studio_compiler_catalogue_v2_project(&engine->providers,snapshot.compiler.active_profile_id,&catalogue); (void)umi_studio_compiler_export_summary_v2(&snapshot.compiler,summary,sizeof(summary)); (void)puts(summary); for (index = 0U; index < catalogue.count; ++index) (void)printf("%-10s %-12s %-24s %s\n",catalogue.rows[index].provider_id,catalogue.rows[index].family,catalogue.rows[index].languages,catalogue.rows[index].available ? "available" : "missing"); umi_studio_compiler_centre_v2_destroy(centre); return 0; }
